'use strict';
const fs=require('node:fs'),path=require('node:path');const {DatabaseSync}=require('node:sqlite');
const cfg=JSON.parse(process.argv[2]);if(cfg.ownerFirst)require('../../server/authority/owner-store.cjs');const C=require('../../server/authority/control-store.cjs'),O=require('../../server/authority/owner-store.cjs'),K=require('../../server/authority/contracts.cjs');
const marker=JSON.parse(fs.readFileSync(path.join(cfg.dataDir,'config','server-authority.json'),'utf8'));
const control=C.openAuthorityStore({dataDir:cfg.dataDir}),owners={};for(const n of K.OWNERS){const filePath=C.ownerFile(cfg.dataDir,n);owners[n]=O.bindOwnerStore({database:new DatabaseSync(filePath),namespace:n,filePath,physicalBinding:marker.physicalBinding,resetEpoch:marker.ownerBindings[n].resetEpoch});}
const raw={exec:DatabaseSync.prototype.exec,prepare:DatabaseSync.prototype.prepare,close:DatabaseSync.prototype.close};let commits=0,qualificationLocks=0,fired=false,unsafeDb;
const kind=db=>raw.prepare.call(db,'PRAGMA database_list').all().find(r=>r.name==='main')?.file?.endsWith('server-authority.sqlite')?'control':'owner';
function hit(stage){if(fired||stage!==cfg.stage)return;fired=true;if(cfg.mode==='kill')process.kill(process.pid,'SIGKILL');if(cfg.mode==='pause'){process.send?.({event:'paused',stage});const end=Date.now()+15000;while(!fs.existsSync(cfg.release)){if(Date.now()>end)process.exit(71);Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,10);}return;}throw Error('injected '+stage);}
DatabaseSync.prototype.exec=function(sql){const k=kind(this);if(k==='owner'&&sql==='COMMIT')hit('before_owner_commit_'+(commits+1));if(k==='control'&&sql==='COMMIT')hit('before_control_commit');if(this===unsafeDb&&sql==='ROLLBACK')throw Error('unsafe rollback');const result=raw.exec.call(this,sql);if(k==='owner'&&sql==='COMMIT')hit('after_owner_commit_'+(++commits));if(k==='control'&&sql==='COMMIT')hit('after_control_commit');if(k==='owner'&&sql==='BEGIN IMMEDIATE'&&raw.prepare.call(this,'PRAGMA user_version').get().user_version===3)hit('after_qualification_lock_'+(++qualificationLocks));if((cfg.mode==='fatal'||(cfg.mode==='fatal-lock'&&qualificationLocks))&&k==='owner'&&sql==='BEGIN IMMEDIATE'&&!unsafeDb){unsafeDb=this;throw Error('after acquired owner BEGIN');}return result;};
DatabaseSync.prototype.close=function(){if(this===unsafeDb)throw Error('unsafe close');return raw.close.call(this);};
DatabaseSync.prototype.prepare=function(sql){const stmt=raw.prepare.call(this,sql);if(/^INSERT INTO lifecycle_operations/.test(sql)){const run=stmt.run;stmt.run=function(...args){hit('before_receipt');const r=run.apply(this,args);hit('after_receipt');return r;};}return stmt;};
try{const q=require('../../server/authority/initial-qualification.cjs').createInitialOwnerQualifier({dataDir:cfg.dataDir,control,resolveOwnerStore:n=>owners[n]});const r=q.qualifyInitialOwners();process.send?.({event:'done',result:r});console.log(JSON.stringify({outcome:r.outcome,receipt:r.receipt}));}catch(e){console.error(e.code||e.message);process.exitCode=1;}finally{for(const [n,fn]of Object.entries(raw))DatabaseSync.prototype[n]=fn;for(const owner of Object.values(owners))owner.close();control.close();}
